"""F. Risk Recommendations generated by the backend decision engine."""

import api_client as api
import pandas as pd
import streamlit as st
from components import (
    RISK,
    header,
    note,
    perf_badge,
    risk_cell,
    safe,
    synthetic_notice,
    table,
)

from sections.shared import select_analysis


def render() -> None:
    header(
        "Risk Recommendations",
        "Actions for the credit risk committee, generated from monitoring results and the decision engine",
    )
    choice = select_analysis("rec_job")
    if not choice:
        return
    rec = safe(lambda: api.get(f"/recommendations/{choice['job_id']}"))
    if not rec:
        return
    synthetic_notice(rec.get("is_synthetic"))
    fg, bg = RISK[rec["risk_category"]]
    st.markdown(
        f'<div class="dg-risk" style="background:{bg};color:{fg};border:1px solid {fg}33">'
        f'<div class="lbl">Risk assessment · {rec["batch_name"]}</div><div class="val">{rec["risk_category"]}</div>'
        f'<div>Drift level <b>{rec["drift_level"]}</b> · overall DIS <b>{rec["overall_dis"]:.3f}</b> · '
        f'decision engine alert <b>{rec["alert_type"] or "none"}</b></div></div>',
        unsafe_allow_html=True,
    )
    left, right = st.columns([3, 2])
    with left:
        st.markdown("#### Recommended actions")
        for a in rec["recommended_actions"]:
            st.markdown(f"- {a}")
        st.markdown("#### Evidence")
        for e in rec["evidence"]:
            st.markdown(f"- `{e}`")
    with right:
        st.markdown("#### Model performance")
        st.markdown(perf_badge(rec["performance_state"]), unsafe_allow_html=True)
        st.write(rec["model_health_message"])
        st.markdown("#### Decision engine output")
        st.write(rec["recommendation"])
        if rec["affected_features"]:
            st.markdown("#### Affected attributes")
            st.write(", ".join(rec["affected_features"]))
    note(
        "DriftGuard never retrains the model or changes loan sanctioning thresholds automatically. "
        "CRITICAL requires confirmed performance degradation from labelled outcomes; drift alone tops out at HIGH."
    )

    hist = safe(lambda: api.get("/analysis/history"), {}) or {}
    latest = hist.get("latest_per_batch", [])
    if latest:
        st.markdown("#### Risk across production batches")
        df = pd.DataFrame(
            [
                {
                    "Batch": r["batch_id"],
                    "Date": r["batch_date"],
                    "Overall DIS": r["overall_dis"],
                    "Risk": r["risk_category"],
                    "Alert": r["alert_type"] or "none",
                    "Performance": r["performance_state"],
                    "Top drivers": ", ".join(r["top_features"]),
                }
                for r in latest
            ]
        )
        table(df, {"Overall DIS": ".3f"}, {"Risk": risk_cell})
